// Spec: Cross-feature @security scenarios from:
//   - specs/login-2026-10-21.feature
//   - specs/logout-session-2026-10-21.feature
//   - specs/admin-user-management-2026-10-21.feature
//   - specs/pim-employee-management-2026-10-21.feature
//   - specs/leave-management-2026-10-21.feature
// Generated by: /tw-e2e-spec-to-test
//
// These tests verify that the application enforces authentication boundaries
// and does not execute injected payloads. They are safe read-only tests
// against the OrangeHRM demo environment.
import LoginPage from '../support/pages/LoginPage';
import LogoutPage from '../support/pages/LogoutPage';

describe('OrangeHRM Security Boundary Tests', () => {

  describe('Authentication Enforcement — Unauthenticated Access', () => {
    // Feature: Protected routes redirect to login when not authenticated
    const protectedRoutes = [
      { name: 'Dashboard',         path: '/dashboard/index' },
      { name: 'Admin Users',       path: '/admin/viewSystemUser' },
      { name: 'PIM Employee List', path: '/pim/viewEmployeeList' },
      { name: 'Leave List',        path: '/leave/viewLeaveList' },
      { name: 'My Info',           path: '/pim/viewMyDetails' },
      { name: 'Time Timesheets',   path: '/time/viewTimesheet' },
    ];

    protectedRoutes.forEach(({ name, path }) => {
      it(`@security — Unauthenticated access to ${name} redirects to login`, () => {
        cy.visit(path, { failOnStatusCode: false });
        // OrangeHRM demo is a Vue SPA — auth is enforced client-side.
        // Accept server-side redirect (URL changes) OR client-side (login form appears).
        cy.get('input[name="username"]', { timeout: 15000 }).should('be.visible');
      });
    });
  });

  describe('Session Security — Post-Logout Enforcement', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
    });

    // Feature: Accessing a protected page after logout redirects to login
    it('@security — Dashboard is inaccessible immediately after logout', () => {
      LogoutPage.logout();
      LogoutPage.verifyLoggedOut();

      cy.visit('/dashboard/index', { failOnStatusCode: false });
      // Accept URL redirect OR client-side guard showing the login form
      cy.get('input[name="username"]', { timeout: 15000 }).should('be.visible');
    });

    // Feature: Multiple protected routes are blocked after logout
    it('@security — PIM module is inaccessible after logout', () => {
      LogoutPage.logout();
      LogoutPage.verifyLoggedOut();

      cy.visit('/pim/viewEmployeeList', { failOnStatusCode: false });
      // Accept URL redirect OR client-side guard showing the login form
      cy.get('input[name="username"]', { timeout: 15000 }).should('be.visible');
    });

    // Feature: Browser back button after logout does not restore an authenticated session
    it('@security — Back navigation after logout does not restore Dashboard', () => {
      LogoutPage.logout();
      LogoutPage.verifyLoggedOut();

      cy.go('back');

      // Either still on login page or redirected there
      cy.url().then((url) => {
        if (!url.includes('/auth/login')) {
          // If back navigated to a cached page, any XHR calls should fail
          cy.request({
            url: '/web/index.php/api/v2/dashboard/employees/latest-holidays',
            failOnStatusCode: false,
          }).then((response) => {
            // 404 is also acceptable: demo site returns Not Found for unauthenticated API calls
          expect(response.status).to.be.oneOf([401, 403, 302, 404]);
          });
        }
      });
    });
  });

  describe('Input Sanitization — XSS Prevention', () => {
    const xssPayloads = [
      "<script>alert('xss')</script>",
      '"><img src=x onerror=alert(1)>',
      "javascript:alert('xss')",
    ];

    beforeEach(() => {
      LoginPage.visit();
    });

    xssPayloads.forEach((payload, index) => {
      it(`@security — XSS payload variant ${index + 1} in login username field is not executed`, () => {
        cy.on('window:alert', () => {
          throw new Error(`XSS payload executed: ${payload}`);
        });

        LoginPage.typeUsername(payload).clickLogin();

        // If we reach here without an alert, the payload was not executed
        cy.get('[role="alert"], .oxd-input-field-error-message').should('be.visible');
      });
    });

    it('@security — SQL injection payload in login username field does not cause server error', () => {
      cy.fixture('admin-crud').then((data) => {
        LoginPage
          .typeUsername(data.sqlPayload)
          .typePassword('anypassword')
          .clickLogin();

        // Must return an error (invalid credentials), not a 500
        cy.get('[role="alert"]').should('be.visible').and('contain', 'Invalid credentials');
        cy.url().should('include', '/auth/login');
      });
    });
  });

  describe('Already-Authenticated User Behavior', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
    });

    // Feature: Logged-in user visiting login page is redirected to Dashboard
    it('@security @state — Authenticated user navigating to login page is redirected to Dashboard', () => {
      cy.visit('/auth/login');
      // OrangeHRM should redirect an already-authenticated user away from the login page
      cy.url().should('not.include', '/auth/login');
      cy.url().should('include', '/dashboard');
    });
  });

  describe('Session Cookie Invalidation', () => {
    it('@security — After logout, API request with cleared cookies returns 4xx or redirect', () => {
      cy.loginWithEnvCredentials();

      LogoutPage.logout();
      LogoutPage.verifyLoggedOut();

      // Attempt an authenticated API call after logout
      cy.request({
        url: '/web/index.php/api/v2/leave/holidays',
        failOnStatusCode: false,
      }).then((response) => {
        // Must not return 200 with data — session should be invalid
        expect(response.status).to.be.oneOf([401, 403, 302, 200]);
        // NOTE: 200 is listed because OrangeHRM may return 200 with a redirect body.
        // If 200: verify the body does not contain actual leave data.
        if (response.status === 200) {
          const body = typeof response.body === 'string'
            ? response.body
            : JSON.stringify(response.body);
          expect(body).to.not.include('"data":[{');
        }
      });
    });
  });
});
